sourceSections.DefineButton2_128/BUTTONCONDACTION on(re:
on(release){
   if(txtEntry.text != "")
   {
      tempNumber = Number(txtEntry.text);
      if(!(tempNumber < 1 or tempNumber > 100))
      {
         k = 1;
         while(k <= 100)
         {
            tempValue = k / tempNumber;
            if(tempValue.toString().indexOf(".") == -1)
            {
               eval("Box_" + k).gotoAndStop(2);
            }
            else
            {
               eval("Box_" + k).gotoAndStop(1);
            }
            k++;
         }
      }
   }
}

sourceSections.DefineButton2_130/BUTTONCONDACTION on(re:
on(release){
   k = 0;
   while(k <= 100)
   {
      eval("Box_" + k).gotoAndStop(1);
      k++;
   }
   txtEntry.text = "";
}

sourceSections.DefineSprite_135/frame_247/DoAction.as:
stop();
_global.quizSection = true;
txtDepth = 1000;
txtEntry.text = "";
drawGrid = function(row, column)
{
   xgridlines = row;
   ygridlines = column;
   distance = 33.7;
   k = 1;
   j = 1;
   while(j <= xgridlines - 1)
   {
      i = 1;
      while(i <= ygridlines - 1)
      {
         removeMovieClip("Box_" + k);
         duplicateMovieClip("Box_Main","Box_" + k,16384 + (k + 4999));
         setProperty(eval("Box_" + k), _X, eval("Box_" + k)._x + distance * i - 152);
         setProperty(eval("Box_" + k), _Y, eval("Box_" + k)._y + distance * j - 152);
         eval("Box_" + k).Numtxt.text = k;
         k++;
         i++;
      }
      j++;
   }
   _global.mcCreateFlag = true;
};
drawGrid(11,11);
Box_Main._visible = false;
txtEntry.restrict = "0-9";
